import{a as e,f as t,g as n,h as r,l as i,t as a,u as o}from"./index-BCUxuupP.js";var s={};function c(a,s){let c=n(`KnowMore`);return r(),i(e,null,[s[0]||=o(`<section data-v-d082328b><div class="section-label" data-v-d082328b> About </div><h1 data-v-d082328b>Why Alygn exists</h1><p data-v-d082328b>Alygn Education is built around one belief: schools, trusts and organisations work better when their systems are aligned. When curriculum, timetable, assessment, data and governance pull in the same direction, quality improves and workload reduces. When they don’t — and in most places they don’t, not fully — the best people in the room end up carrying the weight of that without ever being able to name it.</p><p data-v-d082328b>Alygn exists to name it, map it and help you fix it.</p></section><section data-v-d082328b><div class="card" data-v-d082328b><span class="section-label" data-v-d082328b>Alygn Education</span><h2 data-v-d082328b>A systems-first consultancy</h2><p data-v-d082328b>Alygn isn’t a generic school improvement service or a one-off CPD provider. It’s a systems-alignment consultancy. The work is grounded in the idea that most problems in education aren’t caused by people — they’re caused by misaligned systems that quietly pull in different directions.</p><p data-v-d082328b>The goal is simple: fewer priorities, better connected, clearer decisions, less noise.</p><p data-v-d082328b>Whether it’s curriculum, assessment, data, timetabling, governance or AI integration, the work starts with understanding how the parts fit together — and where they don’t.</p></div></section><section data-v-d082328b><div class="card" data-v-d082328b><span class="section-label" data-v-d082328b>About Gavin</span><h2 data-v-d082328b>The work comes from lived experience</h2><div class="two-col-img-first" data-v-d082328b><div data-v-d082328b><img alt="Gavin" src="/assets/GT-_9-rihtR.png" class="profile-img" data-v-d082328b></div><div data-v-d082328b><p data-v-d082328b>I’m Gavin Taylor. I’ve spent a decade in middle and senior leadership across schools, FE colleges and independent training providers. Roles that stretched me, challenged me, and occasionally broke me in the ways that turn out to matter.</p><p data-v-d082328b>I’ve worked on curriculum and programme design, teaching and learning, assessment and data, quality and compliance, apprenticeship provision, and AI and digital strategy. I’ve seen brilliant people held back by systems that don’t quite work — and I’ve seen what happens when those systems finally align.</p><p data-v-d082328b>Alygn Education is my attempt to take everything I’ve learned in those rooms and turn it into something that makes life easier for the people still in them.</p></div></div></div></section>`,3),t(c)],64)}var l=a(s,[[`render`,c],[`__scopeId`,`data-v-d082328b`]]);export{l as default};